"""1 kHz ratio recognizer, single-file OpenMV N6 build.

Target: OpenMV v5.0.0 / MicroPython v1.28.0-49 / OpenMV N6.
Model: RGB mask + quantized PCA/kNN; Base64 is MicroPython-safe chunked.
Retrained from dataset_1k_single_position (1820 images), with empirical
piecewise frequency-bias correction from the real test setup.
"""

import binascii
import time
import csi
import image as omv_image
from array import array
from machine import I2C, Pin, SoftI2C
from ulab import numpy as np

SCRIPT_STARTED_MS = time.ticks_ms()

# ============================ SETTINGS ============================

# Camera settings match the new 1820-image 1 kHz dataset.
FRAME_SIZE = "QVGA"
PIXFORMAT = "RGB565"
# Match the capture script: allow auto controls to settle for one second,
# then freeze gain/exposure/white balance for repeatable features.
CAMERA_SETTLE_MS = 1000
FREEZE_AUTO_CONTROLS = True

# Keep this True while checking aim and overlays in OpenMV IDE. Set it False
# for the competition after alignment is fixed to remove USB preview overhead.
IDE_STREAM_ENABLED = True

# Phase-one bench mode: the scan frequency is known and fixed at 1 kHz.
SCAN_FREQUENCY_HZ = 1000

# Empirical correction measured on the real oscilloscope/camera setup:
# actual 1..2 kHz: +0; 2..4: +0.2; 4..6: +0.3; 6..8: +0.5;
# 8..10: +0.8 kHz. The classifier sees the biased raw value, not the actual
# value, so the decision points below are shifted into the raw-value domain.
# Where adjacent raw ranges overlap, use their midpoint (rounded to 100 Hz).
# Apply before temporal voting so every output uses the calibrated value.
EMPIRICAL_RAW_2K_BAND_START_HZ = 1900
EMPIRICAL_2K_ADD_HZ = 200
EMPIRICAL_RAW_4K_BAND_START_HZ = 3800
EMPIRICAL_4K_ADD_HZ = 300
EMPIRICAL_RAW_6K_BAND_START_HZ = 5600
EMPIRICAL_6K_ADD_HZ = 500
EMPIRICAL_RAW_8K_BAND_START_HZ = 7400
EMPIRICAL_8K_ADD_HZ = 800
EMPIRICAL_MIN_HZ = 1000
EMPIRICAL_MAX_HZ = 10000

# Three independent classifications are fused with a median. Validation shows
# this rejects the rare single-frame alias without extending acquisition time.
FUSION_FRAMES = 3

# Console output is intentionally short: one Chinese summary per second.
PUBLISH_PERIOD_MS = 1000
ACCEPT_CONFIDENCE = 45
CONSOLE_DEBUG = False

# The console result is more conservative than the three-frame image
# overlay. It clusters about one second of calibrated predictions and suppresses
# isolated aliases before showing a value to the operator.
CONSOLE_WINDOW_FRAMES = 20
CONSOLE_MIN_SAMPLES = 12
# The largest calibrated jump across a band boundary is 0.4x (400 Hz).
CONSOLE_CLUSTER_RADIUS = 0.4
CONSOLE_MIN_CONFIDENCE = 50
CONSOLE_NO_TRACE_RESET_MS = 1200

# OLED remains only an aiming aid and is updated at a low rate.
OLED_ENABLED = True
OLED_MAX_FPS = 2
OLED_I2C_ID = 2
OLED_SCL_PIN = "P7"
OLED_SDA_PIN = "P8"
OLED_ADDRESS = 0x3C
OLED_CONTRAST_PERCENT = 200
OLED_COLUMN_OFFSET = 0
OLED_FAST_START = True

